<template>
  <div class="p-2 payment-page"><el-alert title="人工收款请通过收款登记、主管审核、财务核销流程办理；原直接收款入口已停用。" type="info" :closable="false" class="mb-2" />
    <el-alert v-if="!projectId" title="请先在顶部选择当前物业项目" type="info" :closable="false" show-icon class="mb-2" />
    <el-button v-if="!projectId && canCollect" type="primary" icon="Plus" class="mb-2" @click="handleAddPayment">登记收款</el-button>
    <template v-else>
      <el-card v-show="showSearch" class="mb-2"><el-form :model="query" inline><el-form-item label="当前项目"><el-input :model-value="projectName" disabled /></el-form-item><el-form-item label="收款编号"><el-input v-model="query.paymentNo" clearable /></el-form-item><el-form-item label="房屋"><el-input v-model="query.roomKeyword" clearable /></el-form-item><el-form-item label="付款人"><el-input v-model="query.payerKeyword" clearable /></el-form-item><el-form-item label="收款方式"><el-select v-model="query.paymentMethod" clearable><el-option v-for="x in pm_payment_method" :key="x.value" :label="x.label" :value="x.value" /></el-select></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable><el-option v-for="x in pm_payment_record_status" :key="x.value" :label="x.label" :value="x.value" /></el-select></el-form-item><el-form-item label="收款日期"><el-date-picker v-model="dateRange" type="datetimerange" value-format="YYYY-MM-DD HH:mm:ss" range-separator="至" start-placeholder="开始" end-placeholder="结束" /></el-form-item><el-form-item><el-button type="primary" @click="search">搜索</el-button><el-button @click="resetQuery">重置</el-button></el-form-item></el-form></el-card>
      <el-card><template #header><el-row :gutter="10"><el-col :span="1.5"><el-button v-if="canCollect" type="primary" icon="Plus" @click="handleAddPayment">登记收款</el-button></el-col><el-col :span="1.5"><el-button v-hasPermi="['property:payment:export']" type="warning" plain icon="Download" @click="doExport">导出</el-button></el-col><right-toolbar v-model:show-search="showSearch" @query-table="load" /></el-row></template>
        <el-table v-loading="loading" :data="rows" border><el-table-column label="收款编号" min-width="190"><template #default="s"><el-button v-hasPermi="['property:payment:query']" link type="primary" @click="openDetail(s.row)">{{ s.row.paymentNo }}</el-button></template></el-table-column><el-table-column label="来源登记单" prop="sourceRegistrationNo" min-width="190" /><el-table-column label="客服经办ID" prop="collectorUserId" /><el-table-column label="主管审核ID" prop="reviewerUserId" /><el-table-column label="财务核销ID" prop="writerUserId" /><el-table-column label="房屋" prop="roomFullNameSnapshot" min-width="150" /><el-table-column label="付款人" prop="payerNameSnapshot" min-width="100" /><el-table-column label="收款金额" align="right"><template #default="s">{{ money(s.row.paymentAmount) }}</template></el-table-column><el-table-column label="已核销金额" align="right"><template #default="s">{{ money(s.row.allocatedAmount) }}</template></el-table-column><el-table-column label="收款方式" width="110"><template #default="s"><dict-tag :options="pm_payment_method" :value="s.row.paymentMethod" /></template></el-table-column><el-table-column label="收款时间" prop="paymentTime" min-width="170" /><el-table-column label="状态" width="90"><template #default="s"><dict-tag :options="pm_payment_record_status" :value="s.row.status" /></template></el-table-column><el-table-column label="操作人" prop="createByName" min-width="100" /><el-table-column label="操作" width="130" fixed="right"><template #default="s"><el-button v-hasPermi="['property:payment:query']" link type="primary" @click="openDetail(s.row)">详情</el-button><el-button v-if="s.row.status === 'VALID'" v-hasPermi="['property:payment:reverse']" link type="danger" @click="openReverse(s.row)">冲销</el-button></template></el-table-column></el-table>
        <pagination v-show="total > 0" v-model:page="query.pageNum" v-model:limit="query.pageSize" :total="total" @pagination="load" />
      </el-card>
    </template>
    <PaymentDialog ref="paymentDialog" v-model="paymentDialogVisible" :project-id="projectId" :project-name="projectName" @success="load" />
    <PaymentReverseDialog ref="reverseDialog" :project-id="projectId" @success="handleReverseSuccess" />
    <el-dialog v-model="detailVisible" title="收款详情" width="900px" append-to-body><el-descriptions v-if="detail" :column="2" border class="mb-3"><el-descriptions-item label="收款编号">{{ detail.paymentNo }}</el-descriptions-item><el-descriptions-item label="来源登记单">{{ detail.sourceRegistrationNo || '历史直接收款' }}</el-descriptions-item><el-descriptions-item label="客服经办ID">{{ detail.collectorUserId }}</el-descriptions-item><el-descriptions-item label="主管审核ID">{{ detail.reviewerUserId }}</el-descriptions-item><el-descriptions-item label="财务核销ID">{{ detail.writerUserId }}</el-descriptions-item><el-descriptions-item label="项目">{{ detail.projectName }}</el-descriptions-item><el-descriptions-item label="房屋">{{ detail.roomFullNameSnapshot }}</el-descriptions-item><el-descriptions-item label="付款人">{{ detail.payerNameSnapshot }}</el-descriptions-item><el-descriptions-item label="收款金额">¥ {{ money(detail.paymentAmount) }}</el-descriptions-item><el-descriptions-item label="已核销金额">¥ {{ money(detail.allocatedAmount) }}</el-descriptions-item><el-descriptions-item label="收款方式"><dict-tag :options="pm_payment_method" :value="detail.paymentMethod" /></el-descriptions-item><el-descriptions-item label="交易流水号">{{ detail.transactionNo || '-' }}</el-descriptions-item><el-descriptions-item label="收款时间">{{ detail.paymentTime }}</el-descriptions-item><el-descriptions-item label="状态"><dict-tag :options="pm_payment_record_status" :value="detail.status" /></el-descriptions-item><el-descriptions-item label="操作人">{{ detail.createByName || '-' }}</el-descriptions-item><el-descriptions-item label="备注">{{ detail.remark || '-' }}</el-descriptions-item></el-descriptions><template v-if="detail?.reversal"><h4>冲销信息</h4><el-descriptions :column="2" border class="mb-3"><el-descriptions-item label="冲销单号">{{ detail.reversal.reversalNo }}</el-descriptions-item><el-descriptions-item label="冲销金额">¥ {{ money(detail.reversal.reversalAmount) }}</el-descriptions-item><el-descriptions-item label="冲销时间">{{ detail.reversal.reversalTime }}</el-descriptions-item><el-descriptions-item label="操作人">{{ detail.reversal.createByName || '-' }}</el-descriptions-item><el-descriptions-item label="冲销原因" :span="2">{{ detail.reversal.reason }}</el-descriptions-item></el-descriptions></template><el-alert v-if="detail?.status === 'REVERSED'" title="以下核销明细已随该笔收款冲销失效，仅作为历史记录保留。" type="warning" :closable="false" show-icon class="mb-3" /><el-table :data="detail?.allocations || []" border><el-table-column label="应收编号" prop="receivableNo" min-width="180" /><el-table-column label="收费项目" prop="chargeItemNameSnapshot" /><el-table-column label="账单责任人" prop="responsibleCustomerNameSnapshot" /><el-table-column label="账期" min-width="190"><template #default="s">{{ s.row.periodStart }} ~ {{ s.row.periodEnd }}</template></el-table-column><el-table-column label="本次核销" align="right"><template #default="s">{{ money(s.row.allocationAmount) }}</template></el-table-column><el-table-column label="累计已收" align="right"><template #default="s">{{ money(s.row.receivablePaidAmount) }}</template></el-table-column><el-table-column label="剩余未收" align="right"><template #default="s">{{ money(s.row.receivableOutstandingAmount) }}</template></el-table-column><el-table-column label="支付状态"><template #default="s"><dict-tag :options="pm_payment_status" :value="s.row.paymentStatus" /></template></el-table-column></el-table><template #footer><el-button v-if="detail?.status === 'VALID'" v-hasPermi="['property:payment:reverse']" type="danger" @click="openReverse(detail)">冲销</el-button><el-button @click="detailVisible = false">关闭</el-button></template></el-dialog>
  </div>
</template>

<script setup name="Payment" lang="ts">
import { exportPayment, getPayment, listPayment } from '@/api/property/charge/payment';
import type { PaymentQuery, PaymentVO } from '@/api/property/charge/payment/types';
import { useCurrentProjectStore } from '@/store/modules/currentProject';
import { useDict } from '@/utils/dict';
import { useSearchToggle } from '@/hooks/form/useSearchToggle';
import PaymentDialog from './PaymentDialog.vue';
import PaymentReverseDialog from './PaymentReverseDialog.vue';

const { pm_payment_method, pm_payment_record_status, pm_payment_status } = toRefs<any>(useDict('pm_payment_method', 'pm_payment_record_status', 'pm_payment_status'));
const store = useCurrentProjectStore(), projectId = computed(() => store.currentProjectId), projectName = computed(() => store.currentProjectName), canCollect = computed(() => false);
const rows = ref<PaymentVO[]>([]), total = ref(0), loading = ref(false), detailVisible = ref(false), paymentDialogVisible = ref(false), detail = ref<PaymentVO>(), paymentDialog = ref<InstanceType<typeof PaymentDialog>>(), reverseDialog = ref<InstanceType<typeof PaymentReverseDialog>>(), dateRange = ref<string[]>([]), query = ref<PaymentQuery>({ pageNum: 1, pageSize: 10 });
const { showSearch } = useSearchToggle(); let version = 0;
const money = (v?: number) => Number(v || 0).toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
function params(): PaymentQuery { return { ...query.value, projectId: projectId.value, paymentTimeFrom: dateRange.value?.[0], paymentTimeTo: dateRange.value?.[1] }; }
async function load() { const p = projectId.value, v = ++version; if (!p) { rows.value = []; total.value = 0; return; } loading.value = true; try { const res = await listPayment(params()); if (v !== version || String(p) !== String(projectId.value)) return; rows.value = res.data.rows || []; total.value = res.data.total || 0; } finally { if (v === version) loading.value = false; } }
const search = () => { query.value.pageNum = 1; load(); };
const resetQuery = () => { query.value = { pageNum: 1, pageSize: 10 }; dateRange.value = []; load(); };
const doExport = () => projectId.value && exportPayment(params());
async function handleAddPayment() {
  if (!projectId.value) return ElMessage.warning('请先选择项目');
  if (!canCollect.value) return ElMessage.warning('登记收款需要新增和核销权限');
  await nextTick();
  if (!paymentDialog.value) return ElMessage.error('收款弹窗尚未就绪，请刷新页面后重试');
  paymentDialogVisible.value = true;
}
async function openDetail(row: Partial<PaymentVO>) { if (!row.id) return; const p = projectId.value, v = version; const res = await getPayment(row.id); if (v === version && String(p) === String(projectId.value)) { detail.value = res.data; detailVisible.value = true; } }
function openReverse(row?: any) { if (row) reverseDialog.value?.open(row as PaymentVO); }
async function handleReverseSuccess() { await load(); if (detailVisible.value && detail.value?.id) await openDetail(detail.value); }
watch(projectId, () => { version++; rows.value = []; total.value = 0; detail.value = undefined; detailVisible.value = false; paymentDialogVisible.value = false; reverseDialog.value?.close(); query.value = { pageNum: 1, pageSize: 10 }; dateRange.value = []; load(); });
onMounted(load); onBeforeUnmount(() => version++);
</script>

<style scoped>.payment-page :deep(.el-select){width:180px}.payment-page :deep(.el-date-editor){width:360px}</style>
